// Explota la lista de archivos en N items y clasifica el destino por extensión.
// Solo existen 3 subcarpetas reales en la jornada; 00_INFORME_CONSOLIDADO es un
// ARCHIVO que va a la raíz (folderId de la jornada misma).
const body = $input.first().json.body || $input.first().json;
const folderId = body.folderId;
const archivos = body.archivos || [];

const DEST = {
  RAIZ: '00_INFORME_CONSOLIDADO',
  FOTOS: '02_Evidencias_Fotograficas',
  CHECKLISTS: '03_Checklists_Firmados',
  ACTAS: '04_Actas_Firmas'
};

const clasificar = (nombre, mime) => {
  const n = (nombre || '').toLowerCase();
  const m = (mime || '').toLowerCase();
  if (n.includes('acta') || n.includes('firma')) return DEST.ACTAS;
  if (n.includes('checklist') || n.includes('check') || n.includes('lista')) return DEST.CHECKLISTS;
  if (n.includes('informe') || n.includes('reporte')) return DEST.RAIZ;
  if (m.startsWith('image/') || /\.(jpg|jpeg|png|heic|webp|gif)$/i.test(n)) return DEST.FOTOS;
  if (m === 'application/pdf' || n.endsWith('.pdf')) return DEST.RAIZ;
  return DEST.FOTOS;
};

return archivos.map((a, i) => {
  const destino = a.subcarpeta || clasificar(a.nombre, a.mime_type);
  const esRaiz = destino === DEST.RAIZ;
  return {
    json: {
      index: i,
      folderId,
      subcarpeta: destino,
      esRaiz,
      // Si va a raíz, usamos un nombre dummy que seguramente exista para que la
      // búsqueda del siguiente nodo no falle. En "Resolver destino" ignoramos
      // el resultado si esRaiz=true y usamos folderId directamente.
      subcarpetaBuscar: esRaiz ? DEST.FOTOS : destino,
      fileName: a.nombre,
      mimeType: a.mime_type || 'application/octet-stream'
    },
    binary: {
      data: {
        data: a.base64,
        mimeType: a.mime_type || 'application/octet-stream',
        fileName: a.nombre
      }
    }
  };
});

// Si el archivo va a la RAÍZ (00_INFORME_CONSOLIDADO), subcarpetaId = folderId.
// Si no, tomamos el id de la subcarpeta buscada.
const input = $input.first();
let subcarpetaId;
if (input.json.esRaiz) {
  subcarpetaId = input.json.folderId;
} else {
  const busqueda = $('Buscar subcarpeta').first().json;
  subcarpetaId = busqueda.id;
  if (!subcarpetaId) {
    throw new Error(`No se encontró subcarpeta ${input.json.subcarpeta} dentro de ${input.json.folderId}`);
  }
}
return [{
  json: { ...input.json, subcarpetaId },
  binary: input.binary
}];

// Agrega todos los uploads en un solo item de respuesta.
const items = $input.all();
const archivos = items.map(it => ({
  nombre: it.json.name || it.json.fileName,
  url: it.json.webViewLink || it.json.webContentLink || `https://drive.google.com/file/d/${it.json.id}/view`,
  file_id: it.json.id,
  subcarpeta: it.json.subcarpeta || null
}));
return [{ json: { archivos, cantidad: archivos.length } }];
